using Astrea.RunModifiers;
using DG.Tweening;
using LittleLeo;
using TMPro;
using UnityEngine;
using UnityEngine.UI;

namespace Astrea;

public class SentinelAutoRepairHUD : MouseOverButtons
{
	[Header("Turns Amount")]
	[SerializeField]
	private int repairTimerTurns = 3;

	[Header("Animation")]
	[SerializeField]
	private float delayToShowSentinelAutoRepairHUD;

	[SerializeField]
	private float fillAmountDuration;

	[SerializeField]
	private float delayToRepairSentinel = 0.4f;

	[SerializeField]
	private float companionRepairedAutomaticallyDelayForStartPlayerTurnState = 0.7f;

	[Header("Components")]
	[SerializeField]
	private Image sentinelAutoRepairFilling;

	[SerializeField]
	private TextMeshProUGUI autoRepairCounter;

	[SerializeField]
	private FadeCanvasGroup fadeCanvasGroup;

	private int sentinelBrokenTurnsCounter;

	private bool playerCompletelyCorrupted;

	public float DelayToRepairSentinel => delayToRepairSentinel;

	public float CompanionRepairedAutomaticallyDelayForStartPlayerTurnState => companionRepairedAutomaticallyDelayForStartPlayerTurnState;

	public void Initialize(bool playerCompletelyCorrupted)
	{
		if (playerCompletelyCorrupted)
		{
			this.playerCompletelyCorrupted = true;
			base.gameObject.SetActive(value: false);
		}
		else
		{
			sentinelAutoRepairFilling.fillAmount = 0f;
			fadeCanvasGroup.CanvasGroup.alpha = 0f;
		}
	}

	public void ShowSentinelAutoRepairHUD()
	{
		if (!ReferenceSingleton<RunModifiersManager>.Instance.MalfunctioningSentinelsRunModifierActive && !playerCompletelyCorrupted)
		{
			InvokeAlternatives.Invoke(ReferenceSingleton<CoroutineHandler>.Instance, delayToShowSentinelAutoRepairHUD, delegate
			{
				fadeCanvasGroup.Fade(toggle: true);
			});
		}
	}

	public bool CheckSentinelBrokenTurnsCounter()
	{
		sentinelBrokenTurnsCounter++;
		UpdateRepairTimeCounter();
		if (sentinelBrokenTurnsCounter == repairTimerTurns)
		{
			return true;
		}
		return false;
	}

	public void UpdateRepairTimeCounter()
	{
		autoRepairCounter.SetText((repairTimerTurns - sentinelBrokenTurnsCounter).ToString());
		sentinelAutoRepairFilling.DOFillAmount((float)sentinelBrokenTurnsCounter / (float)repairTimerTurns, fillAmountDuration).SetEase(Ease.OutQuad);
	}

	public void ResetSentinelBrokenTurnsCounter()
	{
		sentinelBrokenTurnsCounter = 0;
		UpdateRepairTimeCounter();
	}

	public override void InitializeActionDescriptionPanel()
	{
		if (positionOverride)
		{
			actionDescriptionPanel.OverridePositions(transformPositionOverrides);
		}
		actionDescriptionPanel.InitializeButtonDescription(buttonDescriptionData, repairTimerTurns - sentinelBrokenTurnsCounter);
	}

	public void OnPlayerCompletelyCorruptedAnimation()
	{
		base.gameObject.SetActive(value: false);
	}
}
